// # 12
// The sequence of triangle numbers is generated by adding the natural numbers. So the 7th triangle number would be 1 + 2 + 3 + 4 + 5 + 6 + 7 = 28.
// The first ten terms would be:
// 1, 3, 6, 10, 15, 21, 28, 36, 45, 55...
// Let us list the factors of the first seven triangle numbers:</p>
// 1: 1
// 3: 1,3
// 6: 1,2,3,6
// 10: 1,2,5,10
// 15: 1,3,5,15
// 21: 1,3,7,21
// 28: 1,2,4,7,14,28
// We can see that 28 is the first triangle number to have over five divisors.
// What is the value of the first triangle number to have over five hundred divisors?
//
// Answer: 76576500

fn has_over_500_divisors(n: u64) -> bool {
    let mut n_divisors = 0;
    for i in 1..=n.isqrt() {
        if n % i == 0 {
            if i * i == n {
                n_divisors += 1
            } else {
                n_divisors += 2 // e.g. 16 is divisible by 2 and by 8, I check until sqrt(16)=4 and count 2 twice
            }
        }
    }

    return n_divisors > 500;
}

fn main() {
    let mut triangle_num = 1;
    let mut over_500 = false;
    let mut i = 1;

    while !over_500 {
        i += 1;
        triangle_num += i;
        over_500 = has_over_500_divisors(triangle_num);
    }

    println!("{}", triangle_num);
}
